namespace sv_25d79aa2d6314da498555055cedf5319.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped (per-circuit) service that holds theme state and notifies
/// all subscribers when it changes. Because Blazor Server uses one
/// circuit per SignalR connection, every interactive component on
/// the page—whether placed in the layout or inside a page—shares
/// the same instance.
/// </summary>
public sealed class ThemeService
{
    private ThemeMode _theme = ThemeMode.System;
    private string _accentColor = "#0d6efd";

    public ThemeMode Theme
    {
        get => _theme;
        set
        {
            if (_theme == value) return;
            _theme = value;
            NotifyChanged();
        }
    }

    public string AccentColor
    {
        get => _accentColor;
        set
        {
            if (_accentColor == value) return;
            _accentColor = value;
            NotifyChanged();
        }
    }

    public event Action? OnChange;

    private void NotifyChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@inject ThemeService Theme
@implements IDisposable

<span class="theme-indicator" style="color: @Theme.AccentColor;" title="Current theme">
    @ThemeIcon @Theme.Theme
</span>

@code {
    private string ThemeIcon => Theme.Theme switch
    {
        ThemeMode.Dark  => "🌙",
        ThemeMode.Light => "☀️",
        _               => "💻"
    };

    protected override void OnInitialized()
    {
        Theme.OnChange += StateHasChanged;
    }

    public void Dispose()
    {
        Theme.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@inject ThemeService Theme
@inject IJSRuntime JS
@implements IDisposable

@code {
    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            Theme.OnChange += OnThemeChanged;
        }

        await ApplyThemeAsync();
    }

    private async void OnThemeChanged()
    {
        await ApplyThemeAsync();
    }

    private async Task ApplyThemeAsync()
    {
        try
        {
            await JS.InvokeVoidAsync("applyTheme", Theme.Theme.ToString().ToLowerInvariant(), Theme.AccentColor);
        }
        catch (JSDisconnectedException) { }
    }

    public void Dispose()
    {
        Theme.OnChange -= OnThemeChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@inject ThemeService Theme
@implements IDisposable

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-4" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="btn-group mb-3" role="group">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                var active = Theme.Theme == mode;
                <button type="button"
                        class="btn @(active ? "btn-primary" : "btn-outline-primary")"
                        @onclick="() => Theme.Theme = mode">
                    @mode
                </button>
            }
        </div>

        <h5 class="card-title">Accent Color</h5>

        <div class="d-flex align-items-center gap-3 mb-3">
            <input type="color"
                   class="form-control form-control-color"
                   value="@Theme.AccentColor"
                   @onchange="OnAccentChanged" />
            <span style="color: @Theme.AccentColor; font-weight: bold;">
                @Theme.AccentColor
            </span>
        </div>

        <p class="text-muted mb-0">
            Changes apply immediately to all components, including the
            header indicator.
        </p>
    </div>
</div>

@code {
    protected override void OnInitialized()
    {
        Theme.OnChange += StateHasChanged;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        Theme.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    public void Dispose()
    {
        Theme.OnChange -= StateHasChanged;
    }
}

// Applies the chosen theme to the <html> element so that even
// statically-rendered content picks up the visual change.
window.applyTheme = (mode, accentColor) => {
    const html = document.documentElement;

    let resolved = mode;
    if (mode === "system") {
        resolved = window.matchMedia("(prefers-color-scheme: dark)").matches
            ? "dark"
            : "light";
    }

    html.setAttribute("data-bs-theme", resolved);
    html.style.setProperty("--app-accent", accentColor);
};

